import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.ResultSet;
import java.sql.Statement;

public class Main {
  public static void main(String[] args) throws Exception {
      Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/mibase", "user", "pass");
      Statement stmt = conn.createStatement();

      // Funciona exactamente igual en la query SQL plana:
      ResultSet rs = stmt.executeQuery("SELECT * FROM clientes LIMIT 5");

      // El bucle while solo correrá 5 veces máximo
      while (rs.next()) {
          System.out.println(rs.getString("nombre"));
      }
  }
}
